import {
  ActivityIndicator,
  ScrollView,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import HeaderCM from '../../components/Header/HeaderCM';
import {useEffect, useState} from 'react';
import {useDashboardServices} from '../../../hooks/useDashboardService';
import {
  Organization,
  PriorityGroup,
  StatusGroup,
  TaskCountRespon,
  TaskGroup,
  TaskHistory,
} from '../../../model/interface/dashboard.interface';
import DashboardBarChart from './DashboardBarChart';
import DashboardPieChart from './DashboardPieChart';
import DashboardDonut from './DashboardDonut';
import {useTranslation} from 'react-i18next';
import {Icon} from '@ui-kitten/components';
import TextCM from '../../components/Text';
import DashboardDetail from './DashboardDetail';
import DashboardCurrentAction from './DashboardCurrentAction';
import ModalFullScreen from '../../components/ModalFullScreen';
import {Color, NavigationName} from '../../../constants';
import Toast from 'react-native-toast-message';
import styles from './styles';
import {useNavigation} from '@react-navigation/native';
import HeaderReport from './HeaderReport';
type FileterValue = {
  dateStart: string;
  dateEnd: string;
  dueDateStart: string;
  dueDateEnd: string;
  modelerId: string;
  org: string;
};

const DashboardScreen = () => {
  const DashBoardServices = useDashboardServices();
  const navigation = useNavigation<any>();
  const {t} = useTranslation();
  const {width} = useWindowDimensions();

  const [selectTab, setSelectTab] = useState<'mine' | 'org'>('org');
  const [priority, setPriority] = useState<PriorityGroup[]>([]);
  const [status, setStatus] = useState<StatusGroup[]>([]);
  const [organization, setOrganization] = useState<Organization[]>([]);
  const [taskCount, setTaskCount] = useState<TaskCountRespon>();
  const [taskCompleted, setTaskCompleted] = useState<TaskGroup[]>([]);
  const [taskLated, setTaskLated] = useState<TaskGroup[]>([]);
  const [taskHistory, setTaskHistory] = useState<TaskHistory[]>([]);

  const [isShowChart, setIsShowChart] = useState(false);

  const [isLoading, setIsLoading] = useState<boolean>(false);

  const getDataDashboard = async (selectTab: 'mine' | 'org') => {
    try {
      setIsLoading(true);
      const filterValue = {} as FileterValue;
      const allValue = await Promise.all([
        DashBoardServices.searchTaskDetail(
          filterValue?.dateStart ?? '',
          filterValue?.dateEnd ?? '',
          filterValue?.dueDateStart ?? '',
          filterValue?.dueDateEnd ?? '',
          filterValue?.modelerId ?? '',
          filterValue?.org ?? '',
          selectTab === 'mine',
        ),
        DashBoardServices.searchTaskOrg(
          filterValue?.dateStart ?? '',
          filterValue?.dateEnd ?? '',
          filterValue?.dueDateStart ?? '',
          filterValue?.dueDateEnd ?? '',
          filterValue?.modelerId ?? '',
          filterValue?.org ?? '',
        ),
        DashBoardServices.searchTaskCount(
          filterValue?.dateStart ?? '',
          filterValue?.dateEnd ?? '',
          filterValue?.dueDateStart ?? '',
          filterValue?.dueDateEnd ?? '',
          filterValue?.modelerId ?? '',
          filterValue?.org ?? '',
          selectTab === 'mine',
        ),
        DashBoardServices.searchTaskHistory(
          filterValue?.dateStart ?? '',
          filterValue?.dateEnd ?? '',
          filterValue?.dueDateStart ?? '',
          filterValue?.dueDateEnd ?? '',
          filterValue?.modelerId ?? '',
          filterValue?.org ?? '',
          selectTab === 'mine',
        ),
      ]);
      const [resDetail, resOrg, resTaskCount, resTaskHistory] = allValue;
      setPriority(resDetail.priority);
      setStatus(resDetail.status);
      setOrganization(resOrg.organization);
      setTaskCount(resTaskCount);
      setTaskCompleted(resDetail.completed);
      setTaskLated(resDetail.missed);
      setTaskHistory(resTaskHistory.history);
    } catch (error) {
      console.error('Có lỗi xảy ra!: ', error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    getDataDashboard(selectTab);
  }, [selectTab]);

  return (
    <>
      <HeaderReport selectTab={selectTab} setSelectTab={setSelectTab} />
      {!isLoading ? (
        <ScrollView style={{flex: 1}}>
          {taskCount && (
            <DashboardDetail
              taskCount={taskCount}
              taskCompleted={taskCompleted}
              taskLated={taskLated}
            />
          )}

          <View style={styles.cardContainer}>
            <TouchableOpacity
              onPress={() => setIsShowChart(true)}
              style={[styles.card, {width: (width - 16 * 3) / 2}]}>
              <View style={styles.contextButton}>
                <Icon name="pie-chart" width={24} height={24} />
                <TextCM style={styles.text}>{t('board.analysis-chart')}</TextCM>
              </View>
            </TouchableOpacity>
            {selectTab === 'org' && (
              <TouchableOpacity
                onPress={() =>
                  navigation.navigate(NavigationName.ContainerReportAssignee)
                }
                style={[styles.card, {width: (width - 16 * 3) / 2}]}>
                <View style={styles.contextButton}>
                  <Icon name="list" width={24} height={24} />
                  <TextCM style={styles.text}>{t('task.task-count')}</TextCM>
                </View>
              </TouchableOpacity>
            )}
          </View>

          {taskHistory && <DashboardCurrentAction taskHistory={taskHistory} />}
        </ScrollView>
      ) : (
        <View style={{flex: 1, justifyContent: 'center', alignItems: 'center'}}>
          <ActivityIndicator color={Color.BgPrimary} size={'large'} />
        </View>
      )}

      <ModalFullScreen
        backdropStyle={{backgroundColor: Color.BgPrimary}}
        paddingBottom={false}
        children={
          <>
            <HeaderCM
              title={t('board.analysis-chart')}
              onPressIconLeft={() => setIsShowChart(false)}
              style={{backgroundColor: Color.BgPrimary}}
            />
            <ScrollView style={{flex: 1, backgroundColor: Color.Background}}>
              {priority && <DashboardBarChart priority={priority} />}
              {status && <DashboardPieChart status={status} />}
              {organization && <DashboardDonut organization={organization} />}
            </ScrollView>
          </>
        }
        isVisible={isShowChart}
      />
    </>
  );
};

export default DashboardScreen;
