import {useEffect, useState} from 'react';
import DashboardTaskRating from '../DashboardTaskRating';
import DashboardAsignee from '../DashboardAsignee';
import {TabView, Tab} from '@ui-kitten/components';
import {
  Assignee,
  Rating,
} from '../../../../model/interface/dashboard.interface';
import {Color, Font} from '../../../../constants';
import {StyleSheet, Text, View} from 'react-native';
import HeaderCM from '../../../components/Header/HeaderCM';
import {useNavigation} from '@react-navigation/native';
import {useDashboardServices} from '../../../../hooks/useDashboardService';
import TextCM from '../../../components/Text';
import {useTranslation} from 'react-i18next';
const styles = StyleSheet.create({
  tabTitle: {
    fontSize: 16,
    fontFamily: Font.InterSemiBold600,
  },
});
type FileterValue = {
  dateStart: string;
  dateEnd: string;
  dueDateStart: string;
  dueDateEnd: string;
  modelerId: string;
  org: string;
};
const ContainerReportAssignee = () => {
  const {t} = useTranslation();
  const DashBoardServices = useDashboardServices();
  const navigation = useNavigation();
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [taskRating, setTaskRating] = useState<Rating[]>([]);
  const [asignee, setAsignee] = useState<Assignee[]>([]);
  const getData = async () => {
    const filterValue = {} as FileterValue;
    const resTaskRating = await DashBoardServices.searchTaskRatingAssignee(
      filterValue?.dateStart ?? '',
      filterValue?.dateEnd ?? '',
      filterValue?.dueDateStart ?? '',
      filterValue?.dueDateEnd ?? '',
      filterValue?.modelerId ?? '',
      filterValue?.org ?? '',
    );
    const resUserByOrgIn = await DashBoardServices.findUserByOrgIn(
      0,
      10000,
      '',
      '',
      resTaskRating.assignee.map(d => d.userId),
    );
    const assgineeWithAvatar = resTaskRating.assignee.map(item => {
      return {
        ...item,
        avatar: resUserByOrgIn.find(h => h.email == item.email)?.imageUrl,
      };
    });
    const ratingWithAvatar = resTaskRating.rating.map(item => {
      return {
        ...item,
        avatar: resUserByOrgIn.find(h => h.email == item.email)?.imageUrl,
      };
    });
    setTaskRating(ratingWithAvatar);
    setAsignee(assgineeWithAvatar);
  };
  useEffect(() => {
    getData();
  }, []);
  return (
    <>
      <HeaderCM
        title={t('task.report-task-quantity')}
        onPressIconLeft={() => navigation.goBack()}
        style={{backgroundColor: Color.BgPrimary}}
      />
      <View style={{flex: 1, backgroundColor: Color.Background}}>
        <TabView
          selectedIndex={selectedIndex}
          onSelect={setSelectedIndex}
          style={{backgroundColor: Color.White, flex: 1}}
          tabBarStyle={{backgroundColor: Color.White, padding: 5, height: 50}}
          swipeEnabled={false}
          indicatorStyle={{backgroundColor: '#3366FF'}}>
          <Tab
            title={evaProps => (
              <TextCM
                {...evaProps}
                style={[
                  styles.tabTitle,
                  {color: selectedIndex === 0 ? '#3366FF' : '#8F9BB3'},
                ]}>
                {t('task.Rated')}
              </TextCM>
            )}>
            <DashboardTaskRating taskRating={taskRating} />
          </Tab>
          <Tab
            title={evaProps => (
              <TextCM
                {...evaProps}
                style={[
                  styles.tabTitle,
                  {color: selectedIndex === 1 ? '#3366FF' : '#8F9BB3'},
                ]}>
                {t('task.total-quantity')}
              </TextCM>
            )}>
            <DashboardAsignee asignee={asignee} />
          </Tab>
        </TabView>
      </View>
    </>
  );
};

export default ContainerReportAssignee;
