import {ITask} from '../../../board/store/interface';
import {useState} from 'react';
import {
  Action,
  IACTION,
} from '../../../board/components/list-task/components/action-task/helper';
import {useTaskService} from '../../../../../hooks/apiHooks/useAPI';
import Toast from 'react-native-toast-message';
import {Icon, Menu, MenuItem} from '@ui-kitten/components';
import ModalConfirmCM from '../../../../components/ModalConfirm';
import {Color} from '../../../../../constants';
import ModalFullScreen from '../../../../components/ModalFullScreen';
import AuthorityAndShareScreen from '../../../../components/Authority';
import {ITaskDetail} from '../task-detail-item/helper';
import {LIST_ACTION} from './helper';
import {useTranslation} from 'react-i18next';
type Props = {
  taskSelect?: ITaskDetail;
  onClose?: () => void;
  listTask: ITaskDetail[];
  setListTask: (state: ITaskDetail[]) => void;
};

const ListActionTaskDetail = ({
  taskSelect,
  onClose,
  listTask,
  setListTask,
}: Props) => {
  const {t} = useTranslation();
  const [isVisible, setIsVisible] = useState<Action | null>(null);

  const Taskservices = useTaskService();
  const handleAction = (action: IACTION) => {
    switch (action.action) {
      case Action.RENAME:
        setIsVisible(Action.RENAME);
        break;
      case Action.DELETE:
        setIsVisible(Action.DELETE);
        break;
      case Action.COPY:
        handleCopyTask();
        break;
      case Action.SAVE_TEMPLATE:
        setIsVisible(Action.SAVE_TEMPLATE);
        break;
      case Action.SHARE_PERMISSIONS:
        setIsVisible(Action.SHARE_PERMISSIONS);
        break;
      default:
        return;
    }
  };

  const handleDelete = async () => {
    try {
      const prevListTask = [...listTask];
      const newListTask = listTask.filter(item => item.id !== taskSelect?.id);
      setListTask(newListTask);
      onClose?.();
      const data = await Taskservices.deleteTaskById(taskSelect?.id || '');
      if (!data) {
        setListTask(prevListTask);
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {}
  };

  const handleCopyTask = async () => {
    try {
      const newData = await Taskservices.copyTemplateTask(taskSelect?.id || '');
      if (newData) {
        onClose?.();
        Toast.show({
          type: 'success',
          text1: t('task.clone-success'),
        });
        const newListTask = [newData, ...listTask];
        setListTask(newListTask);
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {}
  };
  return (
    <>
      <Menu>
        {LIST_ACTION.map(action => {
          return (
            <MenuItem
              onPress={() => handleAction(action)}
              accessoryLeft={<Icon name={action.icon} />}
              key={action.id}
              title={t(action.name)}
            />
          );
        })}
      </Menu>

      <ModalConfirmCM
        isVisible={isVisible === Action.DELETE}
        onClose={() => setIsVisible(null)}
        title={t('HM.titleCancel')}
        content={t('HM.contentCancel')}
        type="cancel"
        labelCancel={t('HM.cancel')}
        labelConfirm={t('CM.labelCancel')}
        styleBtnRight={{backgroundColor: Color.RedE14337}}
        onConfirm={handleDelete}
      />

      <ModalFullScreen
        isVisible={isVisible === Action.SHARE_PERMISSIONS}
        children={
          <AuthorityAndShareScreen
            type="L"
            onClose={() => setIsVisible(null)}
            resource={(taskSelect || {}) as ITask}
          />
        }
      />
    </>
  );
};

export default ListActionTaskDetail;
