import {Icon, List, ListItem} from '@ui-kitten/components';
import {IListTag} from '../../../../../board/store/interface';
import {TextInput, TouchableOpacity, View} from 'react-native';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {Color, Font} from '../../../../../../../constants';
import {useEffect, useState} from 'react';
import TextCM from '../../../../../../components/Text';
import {
  useBoardService,
  useTaskService,
} from '../../../../../../../hooks/apiHooks/useAPI';
import {useAppSelector} from '../../../../../../../hooks/useRedux';
import useDebounce from '../../../../../../../hooks/useDebounce';
import Toast from 'react-native-toast-message';
import {ITaskDetail} from '../../../task-detail-item/helper';
import ButtonCM from '../../../../../../components/Button';
import {isEmpty} from 'lodash';
import {useTranslation} from 'react-i18next';

type Props = {
  onClose: () => void;
  task: ITaskDetail;
  setTask?: (task: ITaskDetail) => void;
};
interface IListTagWithSelected extends IListTag {
  [key: string]: any;
  selected?: boolean;
}

const ModalTags = ({onClose, task, setTask}: Props) => {
  const {t} = useTranslation();
  const TaskService = useTaskService();
  const BoardService = useBoardService();
  const dataAccount = useAppSelector(state => state.account.dataAccount);
  const [tagsDisplay, setTagsDisplay] = useState<IListTagWithSelected[]>([]);
  const [initTags, setInitTags] = useState<IListTagWithSelected[]>([]);
  const [valueText, setValueText] = useState('');
  const valueTextDebounce = useDebounce(valueText);

  const filterTagByName = () => {
    const filtered = initTags.filter(item =>
      item?.name?.toLowerCase()?.includes(valueText.toLowerCase()),
    );
    setTagsDisplay(filtered);
  };
  useEffect(() => {
    filterTagByName();
  }, [valueTextDebounce]);

  const getListTagGroup = async () => {
    const res = (await TaskService.getListTagsByNameAndCustId(
      '',
      dataAccount.custId?.toString() || '7',
    )) as IListTag[];
    const filteredArr = res.map(item => {
      const selected = task?.tags?.includes(item.name);
      return {
        ...item,
        selected,
      };
    });
    setTagsDisplay(filteredArr);
    setInitTags(filteredArr);
  };
  const getInitData = async () => {
    getListTagGroup();
  };

  const toggleSellect = (index: number, item: IListTagWithSelected) => {
    setTagsDisplay(
      tagsDisplay.map((_, i) => {
        return {
          ..._,
          selected: index === i ? !item.selected : _.selected,
        };
      }),
    );
    setInitTags(
      initTags.map((_, i) => {
        return {
          ..._,
          selected: index === i ? !item.selected : _.selected,
        };
      }),
    );
  };

  const handdleAdd = () => {
    const tempListTag = [...tagsDisplay];
    const tempValueText = valueText;
    try {
      if (isEmpty(valueText?.trim())) return;
      if (tagsDisplay.find(item => item.name === valueText)) {
        Toast.show({
          type: 'error',
          text1: t('board.tags-already-exists'),
        });
      } else {
        setValueText('');
        const newTag = {
          name: valueText,
          selected: true,
        } as IListTagWithSelected;
        setTagsDisplay(prev => [newTag, ...prev]);
        setInitTags(prev => [newTag, ...prev]);
      }
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
      setTagsDisplay(tempListTag);
      setValueText(tempValueText);
    }
  };

  const handleUpdate = async () => {
    const tempTask = {...task} as ITaskDetail;
    try {
      const listTagsSellect =
        tagsDisplay.filter(item => item.selected).map(item => item.name) || [];
      onClose();
      setTask && setTask({...task, tags: listTagsSellect});
      await BoardService.updateTask({...task, tags: listTagsSellect});
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
      setTask && setTask(tempTask);
    } finally {
    }
  };

  useEffect(() => {
    getInitData();
  }, []);

  const renderItem = ({
    index,
    item,
  }: {
    index: number;
    item: IListTagWithSelected;
  }) => {
    return (
      <ListItem
        onPress={() => toggleSellect(index, item)}
        title={
          <TextCM
            style={{
              fontSize: 14,
              fontFamily: Font.InterRegular400,
              color: Color.Text,
              lineHeight: 22,
            }}>
            {item?.name}
          </TextCM>
        }
        accessoryRight={
          item.selected ? (
            <Icon name="checkmark" width={16} height={16} />
          ) : (
            <></>
          )
        }
      />
    );
  };
  return (
    <>
      <HeaderCM
        title={t('board.table-tags')}
        titleStyle={{color: Color.Black}}
        fillIconBackLeft={Color.Black}
        contentStyle={{backgroundColor: Color.White}}
        onPressIconLeft={onClose}
      />
      <View style={{padding: 16, flex: 1}}>
        <View style={{flexDirection: 'row', alignItems: 'center'}}>
          <TextInput
            style={{
              flex: 1,
              borderWidth: 1,
              borderColor: Color.borderColor,
              borderRadius: 8,
              paddingHorizontal: 16,
              paddingVertical: 10,
              marginRight: 8, // khoảng cách giữa TextInput và nút Thêm
            }}
            allowFontScaling={false}
            placeholder={t('board.find-or-add-tags')}
            placeholderTextColor={Color.Text}
            value={valueText}
            onChangeText={setValueText}
          />
          <TouchableOpacity
            style={{
              backgroundColor: Color.BgPrimary, // hoặc dùng Color.primary nếu có
              paddingVertical: 10,
              paddingHorizontal: 16,
              borderRadius: 8,
            }}
            onPress={handdleAdd}>
            <TextCM style={{color: 'white'}}>{t('CM.add')}</TextCM>
          </TouchableOpacity>
        </View>
        <List
          // refreshing={refreshing}
          // onRefresh={onRefresh}
          data={tagsDisplay}
          contentContainerStyle={{backgroundColor: '#fff'}}
          onEndReachedThreshold={0.5}
          // onEndReached={fetchNextData}
          renderItem={renderItem}
        />
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            columnGap: 8,
            paddingHorizontal: 16,
          }}>
          <ButtonCM
            style={{flex: 1}}
            onPress={() => handleUpdate()}
            label={t('CM.confirm')}
          />
        </View>
      </View>
    </>
  );
};

export default ModalTags;
