import {Icon, List, ListItem} from '@ui-kitten/components';
import {listAction} from './helper';
import {useTranslation} from 'react-i18next';

type Props = {
  setActionSelect: (data: string) => void;
  isDownload: boolean;
};

const Action = ({setActionSelect, isDownload}: Props) => {
  const {t} = useTranslation();
  return (
    <List
      data={listAction.filter(a => {
        if (!isDownload && a.action === 'download') {
        } else {
          return a;
        }
      })}
      renderItem={({item}) => (
        <ListItem
          onPress={() => setActionSelect(item.action)}
          title={t(item.name)}
          accessoryLeft={props => <Icon {...props} name={item.icon} />}
        />
      )}
    />
  );
};

export default Action;
